@for (container of referencable.$treeChildren;
    track referencable.$gId + '_' + container.referenceName
        ; let i = $index) {

    @let containerKey = referencable.$gId + '_' + container.referenceName;
    @let containerAnchorBox = PositionHelper.computeChildBBox(
        i,
        referencable.$treeChildren.length,
        position
    );










    @if (isExpandedArray[i]) {

        @let realChildren = GraphicalHelper.getAsList(container);

        @for (elem of realChildren; track elem.$gId; let j = $index) {

            @let elemBox = PositionHelper.computeChildBBox(
                j,
                realChildren.length,
                containerAnchorBox
            );





        }

    }
}
